type CartItem = {
  price: number;
  quantity: number;
};

type CartTotalProps = {
  items: CartItem[];
};

export function CartTotal({ items }: CartTotalProps) {
  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return <div className="cart-total">Total: ${total.toFixed(2)}</div>;
}

